from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class VolumeConfirm(Strategy):
    rationale = (
        "Volume-confirmed directional moves indicate strong momentum. By identifying "
        "stocks that show a significant price movement along with high trading volume, we can "
        "target potentially profitable stocks."
    )

    def __init__(self, window: int = 20) -> None:
        self._window = window

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.is_empty() or len(history["symbol"].unique()) < 3:
            return Signal(information_available_at=stamp, weights={})

        strong_moves = (
            history.group_by("symbol")
            .agg(
                (pl.col("close").max() - pl.col("close").min()).alias("price_range"),
                (pl.col("volume")).sum().alias("total_volume"),
            )
            .sort("price_range", descending=True)
            .select(["symbol", "price_range", "total_volume"])
        )

        strong_moves = (
            strong_moves.filter(
                (pl.col("price_range") / pl.col("close").shift(1) - 1.0).abs() > 0.02
                & (pl.col("total_volume") >= 100 * pl.col("close").shift(1))
            )
        ).to_dict(as_series=False)

        symbols = list(strong_moves["symbol"])
        if not symbols:
            return Signal(information_available_at=stamp, weights={})

        weight = 1.0 / len(symbols)
        return Signal(
            information_available_at=stamp,
            weights={s: weight for s in symbols},
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
